```json
{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Pleonasmo é repetir uma ideia que já estava dita em outra palavra. Pode servir para dar ênfase ou, como aqui, para criar humor. O enunciado pede o recurso REITERADO, isto é, que se repete várias vezes no trecho. Por isso, procure um padrão que aparece mais de uma vez.",
   "motivo": "Frases mais curtas e palavras mais simples; ideia 'contida' trocada por 'dita'."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "pleonasmo: a mesma ideia dita duas vezes (subir para cima)",
    "hipérbole: exagero (esperei uma eternidade)",
    "antítese: palavras de sentido oposto (alto × baixo)",
    "paradoxo: ideias que se contradizem, mas convivem (silêncio ensurdecedor)",
    "eufemismo: palavra suave no lugar de uma dura (faleceu = morreu)"
   ],
   "motivo": "Cada figura ganha um exemplo curto, para o aluno comparar sozinho; o eufemismo (alternativa E) faltava."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["reiterado", "repetido, que aparece mais de uma vez"],
    ["pleonasmo", "redundância: palavra a mais que repete o sentido que já estava presente"],
    ["sexagenário", "pessoa com sessenta anos"],
    ["figura de linguagem", "recurso que dá efeito especial ao texto, como exagero, oposição ou repetição"],
    ["liquidez", "dinheiro disponível na hora"]
   ],
   "motivo": "Termos que o aluno pode não conhecer, usados no trecho e na resolução, passam a ser explicados."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "'Reiterado' quer dizer repetido. Então a resposta é um padrão que aparece várias vezes no trecho, e não uma figura que aparece uma vez só.",
   "motivo": "Clareza."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "\"observador social, que observava socialmente\"",
   "motivo": "Mantido o trecho; ajuste só no porque."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "'Observador' já vem de observar, então 'que observava' repete a ideia. 'Socialmente' repete 'social'. É redundância de propósito.",
   "motivo": "Frase mais direta."
  },
  {
   "campo": "resolucao.passos[2].faz",
   "depois": "Ache o segundo e o terceiro padrões",
   "motivo": "Mais simples."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "\"humilhar... tão humilhante\"; \"curvar... tão curvante\"",
   "motivo": "O passo trazia só o segundo trecho na conta; agora a conta mostra os dois, como o 'faz' anuncia, e cabe na tela."
  },
  {
   "campo": "resolucao.passos[2].porque",
   "depois": "Humilhar de modo humilhante diz a mesma coisa duas vezes. Curvar de modo curvante também. É o mesmo padrão do passo anterior, agora duas vezes mais.",
   "motivo": "Mais claro; ligado ao padrão anterior."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "Dizer de novo o que já foi dito é pleonasmo. O tom pomposo e repetitivo do observador soa ridículo, e isso gera o humor.",
   "motivo": "Explica de onde vem o humor."
  },
  {
   "campo": "resolucao.passos[4].conta",
   "depois": "oposição? contradição? exagero? suavização?",
   "motivo": "Inclui o paradoxo, que também é descartado."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "Não há pares de opostos (antítese), nem contradição (paradoxo), nem palavra que suavize (eufemismo). O exagero (hipérbole) aparece só em 'míseras gotas de sua liquidez', uma vez, e não é reiterado.",
   "motivo": "Cada figura descartada ganha o motivo, e a hipérbole é tratada pelo critério 'reiterado'."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "Hipérbole é exagero. 'Míseras gotas de sua liquidez' exagera, mas aparece uma única vez. O enunciado pede o recurso repetido, e o que se repete é a redundância.",
   "motivo": "Frases mais curtas; ligado à palavra 'reiterado'."
  },
  {
   "campo": "resolucao.erradas.E",
   "depois": "Eufemismo suaviza algo duro. Aqui acontece o contrário: o observador usa a palavra forte 'humilhante' e chama o amigo de 'idiota' sem rodeios.",
   "motivo": "Corrige a atribuição: quem chama de 'idiota' é o observador, falando do credor, e ele é o credor, não 'o amigo' em geral; texto mais preciso."
  }
 ],
 "didatica_alertas": [],
 "didatica_ok": true
}
